PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires INTEGER);
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),slug TEXT UNIQUE NOT NULL,profile TEXT NOT NULL,created INTEGER);
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,space_id TEXT REFERENCES spaces(id),token TEXT UNIQUE NOT NULL,details TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'proposed',reply TEXT,created INTEGER);
CREATE TABLE IF NOT EXISTS memories(id TEXT PRIMARY KEY,space_id TEXT REFERENCES spaces(id),details TEXT NOT NULL,created INTEGER);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
